const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const paths = {
  overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  projects:'<path d="M3 7h7l2 2h9v11H3zM3 7V4h7l2 3"/>', pages:'<path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/>',
  appearance:'<circle cx="12" cy="12" r="9"/><path d="M12 3a9 9 0 0 0 0 18z"/>', media:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',
  inbox:'<path d="M3 5h18v14H3zM3 6l9 7 9-7"/>',contacts:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M17 15a5 5 0 0 1 4 5"/>',
  navigation:'<path d="m4 4 16 6-7 3-3 7z"/>',settings:'<path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2 2M16.4 16.4l2 2M5.6 18.4l2-2M16.4 7.6l2-2"/><circle cx="12" cy="12" r="5"/>',
  arrow:'<path d="M6 18 18 6M6 6h12v12"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
  more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  logout:'<path d="M10 4H4v16h6M9 12h12m-4-4 4 4-4 4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',up:'<path d="m7 14 5-5 5 5"/>',down:'<path d="m7 10 5 5 5-5"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',font:'<path d="m5 20 7-17 7 17M8 14h8"/>',video:'<rect x="3" y="5" width="13" height="14" rx="2"/><path d="m16 10 5-4v12l-5-4"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.pages}</svg>`;
const button = (label, action, style='', extra='') => `<button ${/\btype=/.test(extra)?'':'type="button"'} class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const iconButton = (name, action, label, extra='') => { const moreClass=/class="([^"]*)"/.exec(extra)?.[1] || ''; return `<button type="button" class="icon-btn ${moreClass}" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${extra.replace(/class="[^"]*"/,'')}>${icon(name)}</button>`; };
const date = value => value ? new Date(value).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}) : 'Not published yet';
const bytes = value => value > 1048576 ? (value/1048576).toFixed(1)+' MB' : Math.round(value/1024)+' KB';
const sections = [['overview','Overview'],['projects','Projects'],['pages','Pages & content'],['appearance','Appearance'],['media','Media library'],['inbox','Inbox'],['contacts','Contact details'],['navigation','Navigation'],['settings','Settings & backups']];
let state, view='overview', dirty=false, saving=false, filter='all', query='', mediaLimit=40, editingProject, editingPage, selectedInquiry, toastTimer;
const draft = () => state.draft;
async function api(url, options={}) {
  const response = await fetch(url,{...options,headers:{'X-CMS-Request':'1',...(options.body && !(options.body instanceof File) ? {'Content-Type':'application/json'} : {}),...options.headers}});
  let result;
  try { result=await response.json(); } catch { throw new Error('The admin server is unavailable. Start the project with npm run dev.'); }
  if (!response.ok) throw new Error(result.error || 'The request failed.');
  return result;
}
function toast(message,error=false) { const el=$('#toast'); el.textContent=message; el.className='toast show'+(error?' error':''); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('show'),4500); }
function touch() { dirty=true; const el=$('.saved-status'); if(el){ el.textContent='Unsaved changes'; el.classList.add('dirty'); } }
async function save(section=view) {
  if (saving) return;
  saving=true;
  try { const result=await api('/api/admin/draft',{method:'PUT',body:JSON.stringify({content:draft(),revision:state.revision,section})}); state.revision=result.revision; dirty=false; const el=$('.saved-status'); if(el){ el.textContent='Draft saved';el.classList.remove('dirty'); } toast(section.startsWith('Page:')?'Page draft saved. Publish to apply content and visibility.':'Draft saved. Preview it or publish when ready.'); }
  finally { saving=false; }
}
async function load({preserveDraft=false}={}) { const unsaved=preserveDraft&&dirty?state.draft:null,oldRevision=state?.revision; state=await api('/api/admin/state'); if(unsaved){state.draft=unsaved;state.revision=oldRevision;} else dirty=false; render(); }
function field(label,key,value,options={}) { const type=options.type || 'text';return `<div class="field"><label for="f-${key}">${esc(label)}</label>${type==='textarea'?`<textarea id="f-${key}" name="${key}" ${options.attrs||''}>${esc(value)}</textarea>`:`<input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" ${options.attrs||''}>`}${options.help?`<small>${esc(options.help)}</small>`:''}</div>`; }
function empty(title,description,name='inbox',action='') { return `<div class="empty-state"><div class="empty-illustration">${icon(name)}</div><h2>${title}</h2><p>${description}</p>${action}</div>`; }
function head(title,description,actions='') { return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`; }
function tabs(items) { return `<div class="tabs">${items.map(([id,label])=>`<button class="${filter===id?'active':''}" data-action="filter" data-value="${id}">${label}</button>`).join('')}</div>`; }
function toolbar(items,placeholder='Search…') { return `<div class="toolbar">${tabs(items)}<input class="filter-search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(query)}" data-filter></div>`; }
function render() {
  view=sections.some(s=>s[0]===location.hash.slice(1).split('/')[0])?location.hash.slice(1).split('/')[0]:'overview';
  const unread=state.inquiries.filter(i=>i.status==='new').length;
  $('#app').innerHTML=`<aside class="sidebar" id="admin-navigation"><a href="#overview" class="brand"><div class="brand-symbol">w.</div><div class="brand-title">${esc(draft().settings.siteName)}<small>Studio manager</small></div></a>${iconButton('close','close-menu','Close navigation','class="mobile-close"')}<p class="nav-label">WORKSPACE</p><nav class="side-nav">${sections.slice(0,7).map(([id,label])=>`<a href="#${id}" class="${view===id?'active':''}">${icon(id)}${label}${id==='inbox'&&unread?`<span class="nav-count">${unread}</span>`:''}</a>`).join('')}</nav><p class="nav-label" style="margin-top:20px">MANAGE</p><nav class="side-nav">${sections.slice(7).map(([id,label])=>`<a href="#${id}" class="${view===id?'active':''}">${icon(id)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="site-status"><div class="status-line"><i class="green-dot"></i> Local site is running</div><small>${esc(location.host)}</small></div><div class="user"><div class="avatar">${esc(state.displayName.slice(0,2).toUpperCase())}</div><div><strong style="font-size:11px;font-weight:500">${esc(state.displayName)}</strong><small>Administrator</small></div><span style="flex:1"></span>${iconButton('logout','logout','Sign out')}</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${iconButton('menu','menu','Open navigation','class="menu-button" aria-controls="admin-navigation" aria-expanded="false"')}<span>Workspace</span><span>/</span><span>${sections.find(s=>s[0]===view)?.[1]}</span></div><div class="topbar-actions"><div class="global-search">${icon('search')}<input aria-label="Search projects and pages" placeholder="Search your studio" id="global-search"><kbd>⌘ K</kbd><div id="search-results" hidden></div></div><span class="saved-status ${dirty?'dirty':''}">${dirty?'Unsaved changes':'All changes saved'}</span><a class="btn" href="/?preview=draft" target="_blank">${icon('eye')}Preview</a>${button(icon('arrow')+' Publish','publish','dark')}</div></header><main id="content" class="content"></main></div>`;
  renderView();
  $('.sidebar').inert=matchMedia('(max-width:700px)').matches;
}
function renderView() {
  const views={overview:overviewView,projects:projectsView,pages:pagesView,appearance:appearanceView,media:mediaView,inbox:inboxView,contacts:contactsView,navigation:navigationView,settings:settingsView};
  $('#content').innerHTML=views[view]()+`<div class="footer-note"><span>${esc(draft().settings.siteName)} / Studio manager</span><span>Made for the details.</span></div>`;
}
function overviewView() {
  const d=draft();
  return `<div class="overview-intro"><div><p class="section-kicker">YOUR WORKSPACE, AT A GLANCE</p><h1>Your studio, in focus<span style="color:#8d9f46">.</span></h1><p class="muted" style="font-size:12px;margin-top:10px">A little upkeep. A lasting impression. Make yourself at home.</p></div><span class="date">${new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'})}</span></div><div class="stats">${[['projects','Projects',d.projects.length,'Your portfolio, all in one place'],['pages','Website pages',d.pages.length,'Every word has a home'],['media','Media assets',state.media.length,'Images, video, documents & fonts'],['inbox','New inquiries',state.inquiries.filter(i=>i.status==='new').length,'Conversations waiting to happen']].map(([name,label,num,note])=>`<a href="#${name}" class="stat">${icon(name)}<p>${label}</p><strong>${num}</strong><small>${note}</small></a>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><h2>Your website</h2><span class="pill green dot">Running locally</span></div><a href="/" target="_blank" class="site-preview"><div class="mini-mast"><b>${esc(d.settings.siteName)}.</b><span>Services &nbsp; Our work &nbsp; About ↗</span></div><div class="mini-title">WEB & AI<br>STUDIO.</div><img class="preview-art" src="${esc(d.projects[0]?.image)}" alt="Featured project preview"></a><div class="preview-footer"><div><strong style="font-size:12px;font-weight:500">A website worth keeping fresh.</strong><small>Last published: ${date(state.publishedAt)}</small></div><a href="/" class="btn small" target="_blank">Visit website ${icon('arrow')}</a></div></section><section class="panel activity"><div class="panel-head"><h2>Recent activity</h2><a href="#settings" class="muted" style="font-size:11px">Version history ↗</a></div><div class="panel-body" style="padding-top:4px;padding-bottom:4px">${(state.activity.length?state.activity.slice(0,4):[{action:'Your studio is ready',detail:'Content, projects, and design settings are connected.',at:new Date().toISOString()}]).map(a=>`<div class="activity-row"><div class="activity-icon">${icon(a.action.includes('publish')?'arrow':'check')}</div><div><strong>${esc(a.action)}</strong><small>${esc(a.detail)}</small></div><time>${date(a.at)}</time></div>`).join('')}</div></section></div><div><section class="panel"><div class="panel-head"><h2>Pick up from here</h2><span class="muted">↗</span></div><div class="quick-grid">${[['projects','Add a project','Something new to show.'],['pages','Edit your pages','Find the right words.'],['appearance','Make it yours','Colors, type, and motion.'],['inbox','Check your inbox','A new conversation.']].map(([id,title,sub])=>`<a href="#${id}" class="quick-action">${icon(id)}<strong>${title}</strong><small>${sub}</small></a>`).join('')}</div></section><aside class="studio-note">${icon('shield')}<h3>A space to try things.</h3><p>Save your changes as a draft, take a look in Preview, and publish when everything feels right. Previous versions stay in your backups.</p><a href="#settings" style="font-size:11px;font-weight:600;display:block;margin-top:13px">Your version history ↗</a></aside></div></div>`;
}
function projectsView() { return head('Projects','The work that tells your story. Edit, curate, and make room for what’s next.',button(icon('plus')+' New project','new-project','dark'))+toolbar([['all','All projects'],['published','Published'],['draft','Drafts']],'Search projects')+`<div id="collection">${projectCollection()}</div>`; }
function projectCollection() {
  const projects=draft().projects.filter(p=>(filter==='all'||p.status===filter)&&(p.name+' '+p.category).toLowerCase().includes(query.toLowerCase()));
  return `<div class="projects-grid">${projects.map(p=>`<article class="project-card"><button class="project-image" style="display:block;width:100%;padding:0" data-action="edit-project" data-id="${p.id}" aria-label="Edit ${esc(p.name)}"><img src="${esc(p.image)}" alt="${esc(p.alt)}" loading="lazy"><span class="pill ${p.featured?'lime':p.status==='published'?'green':''}">${p.featured?'Featured project':p.status==='published'?'Published':'Draft'}</span></button><div class="project-details"><h3>${esc(p.name)}</h3>${iconButton('more','edit-project','Edit '+p.name,`data-id="${p.id}" class="project-more"`)}<p>${esc(p.category)}</p><div class="project-meta">${icon(p.homeVisible?'eye':'projects')}<span>${p.homeVisible?'Homepage & work':'Work page'}</span><span class="spacer"></span><span>${String(draft().projects.indexOf(p)+1).padStart(2,'0')}</span>${iconButton('up','project-up','Move project up',`data-id="${p.id}"`)}${iconButton('down','project-down','Move project down',`data-id="${p.id}"`)}</div></div></article>`).join('')}<button class="add-card" data-action="new-project">${icon('plus')}A new piece of work</button></div>`;
}
function pagesView() {return head('Pages & content','Every page, every heading, and all the words in between.')+'<p class="inline-note">Visibility changes apply when you publish. Hidden pages are removed from the public site and menus, including while you are signed in. Use Draft preview to review them privately.</p>'+toolbar([['all','All pages'],['visible','Visible'],['hidden','Hidden']],'Search pages')+`<div id="collection">${pageCollection()}</div>`;}
function pageCollection() { const pages=draft().pages.filter(p=>(filter==='all'||(filter==='visible'?p.visible:!p.visible))&&(p.title+' '+p.path).toLowerCase().includes(query.toLowerCase())); return `<section class="panel table-wrap"><table class="data-table"><thead><tr><th>Page</th><th class="hide-mobile">Content fields</th><th>Draft visibility</th><th></th></tr></thead><tbody>${pages.map(p=>`<tr><td><strong>${esc(p.path==='/'?'Homepage':p.heading)}</strong><small>${esc(p.path)}</small></td><td class="hide-mobile">${p.fields.length} editable fields</td><td><span class="pill ${p.visible?'green':''}">${p.visible?'Visible':'Hidden'}</span></td><td>${button(p.visible?'Hide':'Show','toggle-page','small',`data-path="${esc(p.path)}" aria-label="${p.visible?'Hide':'Show'} ${esc(p.path==='/'?'Homepage':p.heading)}"`)} ${button('Edit '+icon('arrow'),'edit-page','small',`data-path="${esc(p.path)}"`)}</td></tr>`).join('')}</tbody></table>${!pages.length?empty('No pages found','Try a different page name or path.','pages'):''}</section>`; }
function fontSelect(label,key,value) {return `<div class="field"><label for="${key}">${label}</label><select id="${key}" data-theme="${key}">${['Hanken','Endcap Grotesk','Fraunces','Arial','Georgia','system-ui',...(draft().theme.customFonts||[]).map(f=>f.name)].map(f=>`<option ${f===value?'selected':''}>${f}</option>`).join('')}</select></div>`;}
function appearanceView() {const t=draft().theme;return head('Appearance','A considered palette. The right type. A little movement.',button(icon('check')+' Save draft','save','dark'))+`<div class="form-layout"><div class="panel"><section class="form-section"><h2>Color palette</h2><p>The five colors that set the tone across your website.</p>${[['accent','Accent','Intro, highlights, and animated footer wordmark'],['paper','Background','Page and contact form backgrounds'],['ink','Text','Headlines and body copy'],['muted','Secondary text','Descriptions and quiet details'],['line','Borders','Rules, dividers, and outlines']].map(([key,label,desc])=>`<div class="color-row"><input type="color" value="${t[key]}" data-theme="${key}" aria-label="${label} color"><label>${label}<small style="display:block">${desc}</small></label><input type="text" value="${t[key]}" data-theme="${key}" aria-label="${label} hex value" pattern="#[a-fA-F0-9]{6}" maxlength="7"></div>`).join('')}</section><section class="form-section"><h2>Typography</h2><p>Original font files are installed and served from your own site.</p>${fontSelect('Body font','bodyFont',t.bodyFont)}${fontSelect('Heading font','headingFont',t.headingFont)}${fontSelect('Editorial / italic font','serifFont',t.serifFont)}<div style="margin-bottom:22px">${button(icon('plus')+' Add a font family','add-font','small')}</div><div class="fields-2"><div class="field"><label for="bodySize">Body size · <span id="bodySize-value">${t.bodySize}</span> px</label><input id="bodySize" type="range" min="12" max="24" value="${t.bodySize}" data-theme="bodySize"></div><div class="field"><label for="headingScale">Heading scale · <span id="headingScale-value">${t.headingScale}</span>×</label><input id="headingScale" type="range" min="0.75" max="1.3" step="0.05" value="${t.headingScale}" data-theme="headingScale"></div></div></section><section class="form-section"><h2>Motion</h2><p>Keep the reference’s animations or choose a quieter presentation.</p><label class="check"><input type="checkbox" data-theme="animations" ${t.animations?'checked':''}>Enable intro, entrance, scroll, drawing, and hover animations</label></section></div><aside class="panel appearance-preview"><div class="panel-head"><h2>Design preview</h2><span class="pill">Live</span></div><div id="type-preview" class="type-specimen" style="background:${t.paper};color:${t.ink}"><p class="section-kicker">A STUDIO WITH SOMETHING TO SAY</p><h2 style="font-family:'${esc(t.headingFont)}'">GOOD<br>DESIGN<span style="color:${t.accent}">.</span><br><em style="font-family:'${esc(t.serifFont)}'">Great details.</em></h2><p style="font-family:'${esc(t.bodyFont)}'">Websites, identities, and products. Thoughtfully designed, carefully built, and always a little different.</p><div class="swatches">${['accent','paper','ink','muted','line'].map(key=>`<i style="background:${t[key]}"></i>`).join('')}</div></div><div class="site-preview" id="color-preview" style="background:${t.accent};min-height:170px"><div class="mini-mast"><b>${esc(draft().settings.siteName)}.</b><span>Made with intention ↗</span></div><div class="mini-title" style="font-size:45px">WEB & AI<br>STUDIO.</div></div><p class="settings-note">This preview changes as you edit. Save a draft to see the full website, then publish to apply your design.</p></aside></div>`;}
function mediaView() { return head('Media library','The images, films, documents, and fonts behind your website.',`<input type="file" id="upload-file" hidden accept="image/png,image/jpeg,image/webp,image/gif,image/avif,video/mp4,application/pdf,.woff,.woff2,.ttf,.otf">${button(icon('upload')+' Upload media','upload','dark')}`)+toolbar([['all','All files'],['image','Images'],['video','Video'],['document','Documents'],['font','Fonts']],'Search media')+`<div id="collection">${mediaCollection()}</div>`; }
function mediaCollection() { const media=state.media.filter(m=>(filter==='all'||m.type===filter)&&(m.name+' '+m.url).toLowerCase().includes(query.toLowerCase()));return media.length?`<div class="media-grid">${media.slice(0,mediaLimit).map(m=>`<button class="media-card" data-action="media-detail" data-url="${esc(m.url)}"><div class="media-thumbnail">${m.type==='image'?`<img src="${esc(m.url)}" alt="" loading="lazy">`:icon(m.type==='font'?'font':m.type==='video'?'video':'pages')}</div><div class="media-info"><strong>${esc(m.name)}</strong><small>${m.type.toUpperCase()} · ${bytes(m.bytes)}${m.uploaded?' · Uploaded':''}</small></div></button>`).join('')}</div>${media.length>mediaLimit?button(`Show more · ${media.length-mediaLimit} remaining`,'more-media','show-more'):''}`:empty('Nothing here just yet','Upload a file, or try a different search.','media'); }
function inboxView() {return head('Inbox','A place for the next good conversation.',button(icon('clock')+' Refresh','refresh-inbox')+button(icon('download')+' Export CSV','export-contacts'))+toolbar([['all','All inquiries'],['new','New'],['read','Read'],['replied','Replied'],['archived','Archived']],'Search inquiries')+`<div id="collection">${inboxCollection()}</div>`;}
function inboxCollection() {const list=state.inquiries.filter(i=>(filter==='all'||i.status===filter)&&(i.name+' '+i.email+' '+i.message).toLowerCase().includes(query.toLowerCase()));return list.length?`<section class="panel table-wrap"><table class="data-table"><thead><tr><th>From</th><th class="hide-mobile">Message</th><th>Status</th><th></th></tr></thead><tbody>${list.map(i=>`<tr class="${i.status==='new'?'unread':''}"><td><div class="inbox-sender"><div class="avatar">${esc(i.name.slice(0,2).toUpperCase())}</div><div><strong>${esc(i.name)}</strong><small>${esc(i.email)}</small></div></div></td><td class="hide-mobile">${esc(i.message.slice(0,65))}<small>${date(i.createdAt)}</small></td><td><span class="pill ${i.status==='new'?'lime':''}">${esc(i.status)}</span></td><td>${button('Open '+icon('arrow'),'inquiry','small',`data-id="${i.id}"`)}</td></tr>`).join('')}</tbody></table></section>`:empty('Your next conversation starts here.','Messages submitted through the website’s contact form arrive in this inbox. You can add notes and track each reply.','inbox','<a class="btn" href="/contact/" target="_blank">View contact form '+icon('arrow')+'</a>');}
function contactsView() {const s=draft().settings;return head('Contact details','Make it easy for the right people to find you.',button(icon('check')+' Save draft','save','dark'))+`<div class="contact-grid"><section class="panel"><div class="panel-head"><h2>Your studio</h2>${icon('contacts')}</div><div class="panel-body">${[['siteName','Studio name'],['tagline','Hero / studio tagline'],['email','Contact email'],['phone','Phone display'],['phoneLink','Phone link'],['location','Location']].map(([key,label])=>field(label,key,s[key],{type:key==='email'?'email':'text',attrs:`data-setting="${key}"`})).join('')}</div></section><div><section class="panel"><div class="panel-head"><h2>The details</h2></div><div class="panel-body">${[['businessHours','Business hours'],['replyTime','Typical reply time'],['instagram','Instagram URL'],['copyright','Footer copyright']].map(([key,label])=>field(label,key,s[key],{attrs:`data-setting="${key}"`})).join('')}</div></section><div class="studio-note">${icon('inbox')}<h3>${state.inquiries.length} contact${state.inquiries.length===1?'':'s'} in your inbox</h3><p>Inquiry records keep the sender’s details, original message, conversation status, and your private notes together.</p><a href="#inbox" style="display:block;font-size:12px;margin-top:15px">Open your inbox ↗</a></div></div></div>`;}
function navigationView() {return head('Navigation','A clear path through your studio. Arrange links and control what appears.',button(icon('check')+' Save draft','save','dark'))+`<section class="panel"><div class="panel-head"><h2>Main menu</h2>${button(icon('plus')+' Add link','add-nav','small')}</div>${draft().navigation.map((n,index)=>`<div class="nav-row"><div><label class="screenreader" for="nav-label-${index}">Link ${index+1} label</label><input id="nav-label-${index}" value="${esc(n.label)}" data-nav="${index}" data-key="label"></div><div><label class="screenreader" for="nav-url-${index}">Link ${index+1} URL</label><input id="nav-url-${index}" value="${esc(n.href)}" data-nav="${index}" data-key="href"></div><label><input type="checkbox" data-nav="${index}" data-key="visible" ${n.visible?'checked':''}>Visible</label><div class="nav-order">${iconButton('up','nav-up','Move link up',`data-index="${index}"`)}${iconButton('trash','remove-nav','Remove link',`data-index="${index}"`)}</div></div>`).join('')}<p class="settings-note">Local paths start with /, for example /work/. Full https:// links work for external destinations.</p></section>`;}
function settingsView() {return head('Settings & backups','A little peace of mind for everything you’ve made.')+`<div class="form-layout"><div><section class="panel"><div class="panel-head"><h2>Content backups</h2>${icon('shield')}</div><div class="panel-body"><p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:20px">Export your content, projects, appearance settings, and inquiries to a JSON file. Importing restores site content to a draft for review.</p><div style="display:flex;gap:10px">${button(icon('download')+' Export backup','export','dark')}${button(icon('upload')+' Import content','import')}<input type="file" id="import-file" accept="application/json,.json" hidden></div></div></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Version history</h2><span class="pill">${state.revisions.length} saved</span></div>${state.revisions.length?state.revisions.map(r=>`<div class="backup-row"><div><strong>${esc(r.label)}</strong><small>${date(r.at)}</small></div>${button('Restore to draft','restore','small',`data-id="${r.id}"`)}</div>`).join(''):'<div class="panel-body"><p class="muted" style="font-size:12px;line-height:1.8">Each time you publish, the previous version is kept here. You can restore it to a draft whenever you need.</p></div>'}</section></div><div><section class="panel"><div class="panel-head"><h2>Administrator access</h2></div><form class="panel-body" id="password-form">${field('Current password','current','',{type:'password',attrs:'autocomplete="current-password" required'})}${field('New password','password','',{type:'password',attrs:'autocomplete="new-password" required minlength="12" maxlength="128"',help:'At least 12 characters. Other sessions will be signed out.'})}${button('Update password','password-submit','dark','type="submit"')}</form></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Workspace information</h2></div><div class="panel-body"><p style="font-size:12px;line-height:2">Storage <span class="muted">· Files on this computer</span><br>Access <span class="muted">· Localhost + admin sign-in</span><br>Content <span class="muted">· ${draft().pages.length} pages / ${draft().projects.length} projects</span><br>Mail delivery <span class="muted">· Inquiries saved to inbox</span></p></div></section></div></div>`;}
function openDialog(title,subtitle,content,footer) {const el=$('#editor');el.innerHTML=`<div class="dialog-header"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div>${iconButton('close','close-editor','Close editor')}</div><div class="dialog-content">${content}</div><div class="dialog-footer">${footer||button('Close','close-editor')}</div>`;if(!el.open)el.showModal();}
function closeEditor() {$('#editor').close(); editingPage=null;editingProject=null;}
async function confirmAction(title,message,action,label='Continue') {const el=$('#confirm');el.innerHTML=`<h2 id="confirm-title">${esc(title)}</h2><p>${esc(message)}</p><div class="confirm-actions">${button('Cancel','cancel-confirm')}${button(esc(label),'accept-confirm','dark')}</div>`;el.showModal();return new Promise(resolve=>{ const listener=async e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!['cancel-confirm','accept-confirm'].includes(a))return;el.removeEventListener('click',listener);el.close();if(a==='accept-confirm'){try{await action();resolve(true);}catch(error){toast(error.message,true);resolve(false);}}else resolve(false);};el.addEventListener('click',listener);el.addEventListener('cancel',()=>{el.removeEventListener('click',listener);resolve(false);},{once:true});});}
function editProject(id) { editingProject=structuredClone(draft().projects.find(p=>p.id===id)||{id:crypto.randomUUID(),name:'',category:'Website & identity',url:'/work/',image:state.media.find(m=>m.type==='image')?.url||'',alt:'',screen:'',description:'',status:'draft',featured:false,homeVisible:true});projectDialog();}
function projectDialog() {const p=editingProject;openDialog(p.name?'Edit project':'A new piece of work','The images and details that introduce your work.',`<img class="dialog-image" id="project-preview-image" src="${esc(p.image)}" alt="Project preview"><form id="project-form">${field('Project name','name',p.name,{attrs:'required maxlength="150"'})}${field('Category / services','category',p.category)}<div class="fields-2"><div class="field"><label for="project-status">Status</label><select name="status" id="project-status"><option value="published" ${p.status==='published'?'selected':''}>Published</option><option value="draft" ${p.status==='draft'?'selected':''}>Draft</option></select></div>${field('Project URL','url',p.url,{attrs:'required'})}</div>${field('Cover image URL','image',p.image,{attrs:'required'})}<div style="margin:-5px 0 20px">${button(icon('media')+' Choose from media library','choose-image','small')}</div>${field('Image description / alt text','alt',p.alt)}${field('Project description','description',p.description,{type:'textarea'})}${field('Monitor screen overlay (optional)','screen',p.screen,{help:'Optional overlay used by layouts that support layered project imagery.'})}<label class="check"><input type="checkbox" name="featured" ${p.featured?'checked':''}>Feature first in the project list</label><label class="check"><input type="checkbox" name="homeVisible" ${p.homeVisible?'checked':''}>Include in selected work on the homepage</label></form>`,`<div>${draft().projects.some(item=>item.id===p.id)?button(icon('trash')+' Remove','remove-project','danger',`data-id="${p.id}"`):''}</div><div>${button('Cancel','close-editor')}${button(icon('check')+' Save project','save-project','dark')}</div>`);}
function readProject() {const data=new FormData($('#project-form'));for(const key of ['name','category','url','image','alt','description','screen','status'])editingProject[key]=data.get(key);editingProject.featured=data.has('featured');editingProject.homeVisible=data.has('homeVisible');}
function editPage(path) {editingPage=structuredClone(draft().pages.find(p=>p.path===path));const p=editingPage;const groups=[...new Set(p.fields.map(f=>f.group))];openDialog(p.path==='/'?'Homepage':esc(p.heading),'Page content and search appearance.',`<p class="drawer-section-title">SEARCH & VISIBILITY</p>${field('Page title','page-title',p.title)}${field('Meta description','page-description',p.description,{type:'textarea'})}<label class="check"><input id="page-visible" type="checkbox" ${p.visible?'checked':''}>Page is visible on the website</label><p class="inline-note">Save this draft, then Publish to apply visibility. Hidden pages can only be opened using the private Draft preview.</p><hr class="divider"><div class="dialog-subnav"><select id="page-group" aria-label="Content section"><option value="all">All sections (${p.fields.length} fields)</option>${groups.map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')}</select><input id="field-search" placeholder="Find text on this page" aria-label="Find text on this page"></div><div id="page-fields"></div>`,`<a href="${esc(p.path)}?preview=draft" target="_blank" class="btn ghost">${icon('eye')}Preview page</a><div>${button('Cancel','close-editor')}${button(icon('check')+' Save page','save-page','dark')}</div>`);renderPageFields();}
function renderPageFields() {const group=$('#page-group').value;const term=$('#field-search').value.toLowerCase();const fields=editingPage.fields.filter(f=>(group==='all'||f.group===group)&&f.value.toLowerCase().includes(term));$('#page-fields').innerHTML=fields.slice(0,120).map(f=>`<div class="page-field"><label for="field-${f.id.replace(':','-')}">${esc(f.group)} · ${esc(f.tag)}</label><textarea id="field-${f.id.replace(':','-')}" data-page-field="${f.id}" style="min-height:${f.value.length>120?110:65}px">${esc(f.value)}</textarea></div>`).join('')+(fields.length>120?'<p class="inline-note">Showing 120 fields. Choose a section or search for specific text to narrow the list.</p>':'');}
function inquiryDialog(id) {selectedInquiry=state.inquiries.find(i=>i.id===id);const i=selectedInquiry;openDialog(esc(i.name),esc(i.email)+' · '+date(i.createdAt),`<span class="pill">${esc(i.interest||'Project inquiry')}</span><div class="message-text">${esc(i.message)}</div><div class="field"><label for="inquiry-status">Conversation status</label><select id="inquiry-status">${['new','read','replied','archived'].map(s=>`<option ${s===i.status?'selected':''}>${s}</option>`).join('')}</select></div>${field('Private notes','inquiry-notes',i.notes,{type:'textarea',help:'Notes are only visible to the administrator.'})}<small>Received from ${esc(i.source||'/contact/')}</small>`,`<a class="btn" href="mailto:${esc(i.email)}?subject=${encodeURIComponent('Re: Your project inquiry')}">${icon('inbox')}Reply by email</a><div>${button('Close','close-editor')}${button('Save conversation','save-inquiry','dark')}</div>`);}
function download(name,data,type) {const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function filteredCollection() {const renderer={projects:projectCollection,pages:pageCollection,media:mediaCollection,inbox:inboxCollection}[view];if(renderer&&$('#collection'))$('#collection').innerHTML=renderer();}
function authScreen(setup=false,error='') {$('#app').innerHTML=`<main class="auth-screen"><section class="auth-brand"><a class="brand" href="/"><div class="brand-symbol">w.</div><div class="brand-title">Webly<small>Studio manager</small></div></a><h1>Behind<br>the <em>good</em><br>work.</h1><p>A LITTLE UPKEEP. A LASTING IMPRESSION.</p><div class="auth-ring"></div></section><section class="auth-form-wrap"><form id="auth-form" class="auth-form" data-setup="${setup}"><p class="section-kicker">YOUR STUDIO, YOUR SPACE</p><h2>${setup?'Make yourself at home.':'Welcome back.'}</h2><p>${setup?'Set up your administrator account to start managing your website.':'Sign in to keep your website looking its best.'}</p>${setup?field('Your name','displayName','',{attrs:'required autocomplete="name" placeholder="Studio administrator"'}):''}${field(setup?'Choose a password':'Password','password','',{type:'password',attrs:`required ${setup?'minlength="12"':''} maxlength="128" autocomplete="${setup?'new-password':'current-password'}"`,help:setup?'Use at least 12 characters. Your password is stored as a secure hash.':''})}${setup?field('Confirm password','confirmPassword','',{type:'password',attrs:'required autocomplete="new-password"'}):''}<button class="btn dark" type="submit">${setup?'Create admin account':'Open your studio'} ${icon('arrow')}</button><div class="error-text" role="alert">${esc(error)}</div><footer>Local workspace · <a href="/">Back to your website ↗</a></footer></form></section></main>`;}
document.addEventListener('click',async event=>{
 const element=event.target.closest('[data-action]');if(!element)return;const action=element.dataset.action;
 try {
  if(action==='menu'){$('.sidebar').classList.add('open');$('.sidebar').inert=false;element.setAttribute('aria-expanded','true');}
  if(action==='close-menu'){$('.sidebar').classList.remove('open');$('.sidebar').inert=matchMedia('(max-width:700px)').matches;const menu=$('[data-action=menu]');menu?.setAttribute('aria-expanded','false');menu?.focus();}
  if(action==='save')await save();
  if(action==='refresh-inbox'){const fresh=await api('/api/admin/state');state.inquiries=fresh.inquiries;state.activity=fresh.activity;render();toast('Inbox refreshed.');}
  if(action==='add-font'){const fonts=state.media.filter(m=>m.type==='font');openDialog('Add a font family','Choose an installed font file or upload a new one in the media library.',`${field('Font family name','font-name','',{attrs:'required maxlength="60" placeholder="My Studio Sans"'})}<div class="field"><label for="custom-font-file">Font file</label><select id="custom-font-file">${fonts.map(f=>`<option value="${esc(f.url)}">${esc(f.name)}</option>`).join('')}</select></div>`,`${button('Cancel','close-editor')}${button('Add font family','save-font','dark')}`);}
  if(action==='save-font'){const name=$('#f-font-name').value.trim(),url=$('#custom-font-file').value;if(!/^[a-zA-Z][a-zA-Z0-9 -]{1,59}$/.test(name)){toast('Use a font family name with letters, spaces or numbers.',true);return;}draft().theme.customFonts||=[];if(draft().theme.customFonts.some(f=>f.name===name)){toast('That font family is already registered.',true);return;}draft().theme.customFonts.push({name,url});const style=document.createElement('style');style.textContent=`@font-face{font-family:${JSON.stringify(name)};src:url(${JSON.stringify(url)})}`;document.head.append(style);touch();closeEditor();renderView();toast('Font family added. Select it for your body, headings or italics.');}

  if(action==='publish')await confirmAction('Ready to publish?','Your saved draft will become the live version on your website. The previous version will be kept in backups.',async()=>{if(dirty)await save();const result=await api('/api/admin/publish',{method:'POST',body:JSON.stringify({revision:state.revision})});state.revision=result.revision;state.publishedAt=result.publishedAt;await load();toast('Published. Your website is up to date.');},'Publish website');
  if(action==='logout'){if(dirty&&!await confirmAction('Leave unsaved changes?','Your last saved draft is safe. Any unsaved edits in this tab will be lost.',async()=>{},'Sign out'))return;await api('/api/admin/logout',{method:'POST'});state=null;authScreen();}
  if(action==='filter'){filter=element.dataset.value;document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.value===filter));mediaLimit=40;filteredCollection();}
  if(action==='new-project')editProject();
  if(action==='edit-project')editProject(element.dataset.id);
  if(action==='close-editor')closeEditor();
  if(action==='save-project'){const form=$('#project-form');if(!form.reportValidity())return;readProject();if(editingProject.featured)draft().projects.forEach(p=>p.featured=false);const index=draft().projects.findIndex(p=>p.id===editingProject.id);if(index<0)draft().projects.push(editingProject);else draft().projects[index]=editingProject;touch();await save('Projects');closeEditor();renderView();}
  if(action==='remove-project')await confirmAction('Remove this project?','The project will be removed from your draft. Its media files and previous published versions will be kept.',async()=>{draft().projects=draft().projects.filter(p=>p.id!==element.dataset.id);touch();await save('Projects');closeEditor();renderView();},'Remove project');
  if(action==='project-up'||action==='project-down'){const arr=draft().projects,index=arr.findIndex(p=>p.id===element.dataset.id),other=index+(action==='project-up'?-1:1);if(other<0||other>=arr.length)return;[arr[index],arr[other]]=[arr[other],arr[index]];touch();filteredCollection();}
  if(action==='choose-image'){readProject();const images=state.media.filter(m=>m.type==='image');openDialog('Choose a cover image','Select an image from your media library.',`<input id="media-picker-search" placeholder="Search images" aria-label="Search images" style="margin-bottom:20px"><div class="selection-grid" id="media-picker">${images.map(m=>`<button data-action="pick-image" data-url="${esc(m.url)}" data-name="${esc(m.name)}"><img src="${esc(m.url)}" alt="" loading="lazy"><small>${esc(m.name)}</small></button>`).join('')}</div>`,button('Back to project','back-project'));}
  if(action==='pick-image'){editingProject.image=element.dataset.url;projectDialog();}
  if(action==='back-project')projectDialog();
  if(action==='edit-page')editPage(element.dataset.path);
  if(action==='toggle-page'){const page=draft().pages.find(p=>p.path===element.dataset.path);page.visible=!page.visible;touch();await save('Page visibility: '+page.path);renderView();toast((page.visible?'Page shown':'Page hidden')+' in draft. Publish to apply this change.');}
  if(action==='save-page'){editingPage.title=$('#f-page-title').value;editingPage.description=$('#f-page-description').value;editingPage.visible=$('#page-visible').checked;draft().pages[draft().pages.findIndex(p=>p.path===editingPage.path)]=editingPage;touch();await save('Page: '+editingPage.path);closeEditor();renderView();}
  if(action==='upload')$('#upload-file').click();
  if(action==='more-media'){mediaLimit+=40;filteredCollection();}
  if(action==='media-detail'){const m=state.media.find(m=>m.url===element.dataset.url);openDialog(esc(m.name),m.type.toUpperCase()+' · '+bytes(m.bytes),`${m.type==='image'?`<img class="dialog-image" src="${esc(m.url)}" alt="Media preview">`:m.type==='video'?`<video controls class="dialog-image" src="${esc(m.url)}"></video>`:''}${field('File URL','media-url',m.url,{attrs:'readonly'})}<p class="muted" style="font-size:12px">Use this path when choosing project images or linking a document from your website.</p>`,`<a class="btn" href="${esc(m.url)}" target="_blank">Open file ${icon('arrow')}</a>${button('Copy URL','copy-media','dark',`data-url="${esc(m.url)}"`)}`);}
  if(action==='copy-media'){await navigator.clipboard.writeText(element.dataset.url);toast('File URL copied.');}
  if(action==='inquiry')inquiryDialog(element.dataset.id);
  if(action==='save-inquiry'){await api('/api/admin/inquiry',{method:'PUT',body:JSON.stringify({id:selectedInquiry.id,status:$('#inquiry-status').value,notes:$('#f-inquiry-notes').value})});closeEditor();await load({preserveDraft:true});toast('Conversation updated.');}
  if(action==='add-nav'){draft().navigation.push({label:'New link',href:'/',visible:true});touch();renderView();}
  if(action==='nav-up'){const i=Number(element.dataset.index);if(i>0){[draft().navigation[i],draft().navigation[i-1]]=[draft().navigation[i-1],draft().navigation[i]];touch();renderView();}}
  if(action==='remove-nav'){draft().navigation.splice(Number(element.dataset.index),1);touch();renderView();}
  if(action==='export'){if(dirty)await save();const data=await api('/api/admin/export');download('webly-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data,null,2),'application/json');toast('Backup downloaded.');}
  if(action==='export-contacts'){const cell=v=>'"'+String(v||'').replace(/"/g,'""')+'"';const rows=[['Name','Email','Status','Interest','Message','Received'],...state.inquiries.map(i=>[i.name,i.email,i.status,i.interest,i.message,i.createdAt])];download('endcap-contacts.csv',rows.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv');toast('Contact export downloaded.');}
  if(action==='import')$('#import-file').click();
  if(action==='restore')await confirmAction('Restore this version?','This replaces your current draft with the selected version. The live website stays as it is until you publish.',async()=>{await api('/api/admin/restore',{method:'POST',body:JSON.stringify({id:element.dataset.id})});await load();toast('Version restored to draft.');},'Restore draft');
 }catch(error){toast(error.message,true);}
});
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.matches('[data-filter]')){query=el.value;mediaLimit=40;filteredCollection();}
 if(el.dataset.setting){draft().settings[el.dataset.setting]=el.value;touch();}
 if(el.dataset.nav){draft().navigation[Number(el.dataset.nav)][el.dataset.key]=el.type==='checkbox'?el.checked:el.value;touch();}
 if(el.dataset.theme){const key=el.dataset.theme;draft().theme[key]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;touch();document.querySelectorAll(`[data-theme="${key}"]`).forEach(other=>{if(other!==el)other.value=el.value;});if($('#'+key+'-value'))$('#'+key+'-value').textContent=el.value;const t=draft().theme;if($('#type-preview')){$('#type-preview').style.background=t.paper;$('#type-preview').style.color=t.ink;$('#type-preview h2').style.fontFamily=t.headingFont;$('#type-preview h2 span').style.color=t.accent;$('#type-preview em').style.fontFamily=t.serifFont;$('#type-preview p:not(.section-kicker)').style.fontFamily=t.bodyFont;$('#type-preview p:not(.section-kicker)').style.fontSize=t.bodySize+'px';$('#color-preview').style.background=t.accent;$('#type-preview .swatches').innerHTML=['accent','paper','ink','muted','line'].map(k=>`<i style="background:${esc(t[k])}"></i>`).join('');}}
 if(el.dataset.pageField){editingPage.fields.find(f=>f.id===el.dataset.pageField).value=el.value;}
 if(el.id==='field-search')renderPageFields();
 if(el.id==='media-picker-search')document.querySelectorAll('#media-picker button').forEach(b=>b.hidden=!b.dataset.name.toLowerCase().includes(el.value.toLowerCase()));
 if(el.id==='global-search'){const q=el.value.toLowerCase().trim(),results=$('#search-results');results.hidden=!q;results.className='search-results';if(q){const items=[...draft().projects.filter(p=>p.name.toLowerCase().includes(q)).map(p=>({label:p.name,kind:'Project',href:'#projects',action:'edit-project',id:p.id})),...draft().pages.filter(p=>(p.title+p.path).toLowerCase().includes(q)).map(p=>({label:p.heading,kind:p.path,href:'#pages',action:'edit-page',path:p.path}))].slice(0,8);results.innerHTML=items.length?items.map(i=>`<a href="${i.href}" data-action="${i.action}" ${i.id?`data-id="${i.id}"`:`data-path="${esc(i.path)}"`}>${esc(i.label)}<small>${esc(i.kind)}</small></a>`).join(''):'<p style="padding:10px;font-size:12px">No results found.</p>';}}
});
document.addEventListener('change',async event=>{
 const el=event.target;
 if(el.id==='page-group')renderPageFields();
 if(el.matches('select[data-setting]')){draft().settings[el.dataset.setting]=el.value;touch();}
 try{
  if(el.id==='upload-file'&&el.files[0]){const file=el.files[0];toast('Uploading '+file.name+'…');await api('/api/admin/upload?name='+encodeURIComponent(file.name),{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'}});const fresh=await api('/api/admin/state');state.media=fresh.media;state.activity=fresh.activity;renderView();toast('Uploaded. Your file is in the media library.');}
  if(el.id==='import-file'&&el.files[0]){const backup=JSON.parse(await el.files[0].text());await confirmAction('Import this backup?','Site content in this file will replace the current draft. The live site and inquiry inbox stay unchanged.',async()=>{await api('/api/admin/import',{method:'POST',body:JSON.stringify(backup)});await load();toast('Backup imported to draft.');},'Import content');}
 }catch(error){toast(error.message,true);}
});
document.addEventListener('submit',async event=>{
 event.preventDefault();
 try{
  if(event.target.id==='auth-form'){const form=event.target,data=Object.fromEntries(new FormData(form)),setup=form.dataset.setup==='true';if(setup&&data.password!==data.confirmPassword){$('.error-text').textContent='The passwords do not match.';return;}const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await api(setup?'/api/admin/setup':'/api/admin/login',{method:'POST',body:JSON.stringify(data)});await load();}catch(error){$('.error-text').textContent=error.message;submit.disabled=false;}}
  if(event.target.id==='password-form'){const data=Object.fromEntries(new FormData(event.target));await api('/api/admin/password',{method:'POST',body:JSON.stringify(data)});event.target.reset();toast('Password updated. Other sessions are signed out.');}
  if(event.target.id==='project-form')document.querySelector('[data-action="save-project"]').click();
 }catch(error){toast(error.message,true);}
});
window.addEventListener('hashchange',async()=>{if(!state)return;filter='all';query='';mediaLimit=40;render();if(view==='inbox'||view==='overview'){const current=view;try{const fresh=await api('/api/admin/state');state.inquiries=fresh.inquiries;state.activity=fresh.activity;if(view===current)render();}catch(error){toast(error.message,true);}}});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();$('#global-search')?.focus();}if((event.ctrlKey||event.metaKey)&&event.key==='s'&&state){event.preventDefault();save().catch(e=>toast(e.message,true));}});
try{const status=await api('/api/admin/session');if(status.authenticated)await load();else authScreen(status.setupRequired);}catch(error){authScreen(false,error.message);}

matchMedia('(max-width:700px)').addEventListener('change',event=>{const side=$('.sidebar');if(side)side.inert=event.matches&&!side.classList.contains('open');});
